-- Xmip Storage on PostgreSQL: the administration database's schema.
--
-- Generated by xmip-core-persist (storage::schema), the definition the
-- backend reads and writes by; do not edit. `cargo test --test database`
-- at the estate root fails when this file differs from what it writes.
-- What to run, in what order and why: README.md beside this file.
--
-- Run as a superuser, connected to the xmip_administration database.

SET ROLE xmip_owner;
CREATE SCHEMA xmip AUTHORIZATION xmip_owner;

-- each schema version the database has held, the one it was made at and each an upgrade reached, with when; the version it holds is the highest.
CREATE TABLE xmip.schema_version (
    version integer NOT NULL,
    recorded_at timestamptz NOT NULL,
    CONSTRAINT schema_version_key PRIMARY KEY (version)
);

-- registration, membership, Modules, Handlers, deployment and operator state, and when each was last written.
CREATE TABLE xmip.administration (
    kind text NOT NULL,
    id uuid NOT NULL,
    body bytea NOT NULL,
    updated_at timestamptz NOT NULL,
    CONSTRAINT administration_key PRIMARY KEY (kind, id)
);

CREATE INDEX administration_updated ON xmip.administration (kind, updated_at);

-- each secret a Location names, by its name: its kind, its value sealed by Xmip under the administration database's data key, and when and by whom it was last set; its value is never read back out.
CREATE TABLE xmip.secret (
    secret uuid NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    sealed bytea NOT NULL,
    set_at timestamptz NOT NULL,
    set_by text NOT NULL,
    CONSTRAINT secret_key PRIMARY KEY (secret),
    CONSTRAINT secret_unique UNIQUE (name)
);

CREATE INDEX secret_name ON xmip.secret (name);

-- The schema version it holds now.
INSERT INTO xmip.schema_version (version, recorded_at) VALUES (1, now());

GRANT USAGE ON SCHEMA xmip TO xmip_storage;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA xmip TO xmip_storage;
RESET ROLE;
